import re
from datetime import datetime
with open('./doc/Patient.md') as h:
    pat=h.read()
with open('./doc/Laboratory.md') as h:
    lab=h.read()
# Find abnormal creatinine patients (>=1.0)
abn=re.findall(r'[Pp]atient\s+(\d+).*?([Cc]reatinine[^,]*)(\d\.?[0-9]*)(?:\s*mg|mg/dL|dL)',lab,re.I|re.S)
abn_ids=set([a[0] for a in abn if float(a[2])>=1.0])
print('Abnormal IDs:',len(abn_ids))
# Find birthday patterns
bd_pat=re.findall(r'[Pp]atient\s+(\d+).*?born.*?([A-Za-z]+\s+\d{1,2},?\s+\d{4})',pat,re.I|re.S)
print('Birthdays found:',len(bd_pat))
# Parse birthdays and calculate age
def parse_bd(d):
    try:
        return datetime.strptime(d, '%B %d, %Y')
    except:
        try:
            return datetime.strptime(d, '%B %d %Y')
        except:
            return None
# Get birth years
birth_dates={}
for pid, d in bd_pat:
    dt=parse_bd(d)
    if dt:
        birth_dates[pid]=dt
print('Valid birth dates:',len(birth_dates))
# Calculate ages as of 2025
reference=datetime(2025,1,1)
under70=[pid for pid in abn_ids if birth_dates.get(pid) and (reference-birth_dates[pid]).days/365.25<70]
print('Under 70 count:',len(under70))
print('Under 70:',sorted(under70)[:10])
# Show sample
for pid in list(under70)[:5]:
    if pid in birth_dates:
        age=(reference-birth_dates[pid]).days/365.25
        print(f'{pid}: DOB={birth_dates[pid].strftime("%Y-%m-%d")}, Age={age:.0f}')

